<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {api} from './api'
const props=defineProps<{admin:boolean}>(),emit=defineEmits<{error:[string]}>()
const items=ref<any[]>([]),selected=ref<any>(null),detail=ref<any>(null),transcript=ref(''),alignment=ref('[]'),redactions=ref('[]'),speaker=ref(''),singleSpeaker=ref(false),listened=ref(false),verified=ref(false),deidentified=ref(false),busy=ref(false)
async function load(){items.value=await api('community/speech-contributions')}
onMounted(()=>load().catch(e=>emit('error',String(e))))
async function select(item:any){selected.value=item;detail.value=await api('community/speech-contributions/'+item.id);transcript.value='';alignment.value='[]';redactions.value='[]';speaker.value='';singleSpeaker.value=false;listened.value=false;verified.value=false;deidentified.value=false}
async function review(decision:string){busy.value=true;try{await api('community/speech-contributions/'+selected.value.id+'/review','POST',{decision,verified_transcript:transcript.value,transcript_verified:verified.value,audio_reviewed_in_full:listened.value,deidentification_verified:deidentified.value,speaker_key:speaker.value,single_speaker_verified:singleSpeaker.value,alignment:JSON.parse(alignment.value),redactions:JSON.parse(redactions.value)});await load();selected.value=null}catch(e){emit('error',String(e))}finally{busy.value=false}}
async function remove(id:string){if(!window.confirm('Ștergi contribuția și revoci eligibilitatea ei pentru exporturi viitoare?'))return;try{await api('community/speech-contributions/'+id,'DELETE');await load();selected.value=null}catch(e){emit('error',String(e))}}
async function exportDataset(){try{const result=await api('community/speech-contributions/export','POST',{dataset_id:crypto.randomUUID()});const url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='wisemed-speech-dataset-'+result.dataset_id+'.json';link.click();URL.revokeObjectURL(url)}catch(e){emit('error',String(e))}}
</script>
<template><section class="paper"><h2>Contribuții vocale</h2><p>Audio sensibil și textele brute au retenție de 7 zile. Mostrele aprobate păstrează audio mascat și ținta verificată până la 365 de zile. Identificatorii de vorbitor din manifest sunt pseudonimi și trebuie folosiți pentru separarea antrenării de evaluare.</p><Button v-if="admin" label="Exportă manifestul mostrelor aprobate" @click="exportDataset"/>
<div class="table-wrap"><table><thead><tr><th>Contribuție / secțiune</th><th>Stare</th><th>Upload</th><th>Acțiuni</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td>{{item.id}}<br/>{{item.section_id}}</td><td>{{item.state}}</td><td>{{item.uploaded}} / {{item.byte_length}}</td><td><Button label="Detalii" text @click="select(item).catch(e=>emit('error',String(e)))"/><Button label="Șterge" text severity="danger" @click="remove(item.id)"/></td></tr></tbody></table></div></section>
<section v-if="selected&&detail" class="paper"><h2>Revizuire · {{selected.id}}</h2><audio v-if="selected.state!=='uploading'" controls :src="'/v1/community/speech-contributions/'+selected.id+'/audio'"/><details><summary>Proveniență și texte sursă · conținut sensibil</summary><pre style="white-space:pre-wrap">{{JSON.stringify(detail.metadata,null,2)}}</pre></details>
<template v-if="admin"><label>Identificator pseudonim al vorbitorului<InputText v-model="speaker" minlength="8" maxlength="64" placeholder="Același identificator pentru aceeași voce, fără nume sau date personale"/></label><label class="check"><input type="checkbox" v-model="singleSpeaker"/> Am verificat că există un singur vorbitor și identificatorul lui este consecvent în dataset.</label><label>Transcriere fidelă verificată a întregului audio<Textarea v-model="transcript" rows="4" maxlength="16000"/></label><label>Aliniere verificată · JSON, intervale relative la acest fișier în milisecunde<Textarea v-model="alignment" rows="6" placeholder='[{"start_ms":0,"end_ms":700,"text":"Ficat"}]'/></label><label>Intervale de mascat · JSON<Textarea v-model="redactions" rows="3" placeholder='[{"start_ms":700,"end_ms":1400}]'/></label><p class="muted">Alinierea trebuie să reproducă transcrierea verificată. Intervalele sensibile se maschează în audio, iar textul lor se exclude din ținta exportată. Verifică și datele personale omise sau recunoscute greșit de STT.</p>
<label class="check"><input type="checkbox" v-model="listened"/> Am ascultat și revizuit întregul audio.</label><label class="check"><input type="checkbox" v-model="verified"/> Transcrierea și intervalele reprezintă fidel audio.</label><label class="check"><input type="checkbox" v-model="deidentified"/> Am verificat de-identificarea textului, vocii și intervalelor sensibile, inclusiv omisiunile STT.</label><div class="actions"><Button label="Necesită revizuire" severity="secondary" :disabled="busy" @click="review('needs_review')"/><Button label="Respinge" severity="danger" :disabled="busy" @click="review('rejected')"/><Button label="Aprobă pentru dataset" :disabled="busy||!listened||!verified||!deidentified||!transcript||!singleSpeaker||!speaker" @click="review('approved_for_dataset')"/></div></template></section></template>
